      "content": "{\n  \"name\": \"@michengai/dsh-codex-ui\",\n  \"version\": \"2.0.11\",\n  \"description\": \"DSH Codex UI — 为 DeepSeek Harness 提供极速历史召回、全屏设置皮肤、原生物理毛玻璃换肤与模块化侧栏 · Input enhancement, settings skin, native glass theme, and modular sidebar for DSH\",\n  \"license\": \"Apache-2.0\",\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"registry\": \"https://registry.npmjs.org/\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/MichengAI/dsh-codex-ui.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/MichengAI/dsh-codex-ui/issues\"\n  },\n  \"homepage\": \"https://github.com/MichengAI/dsh-codex-ui#readme\",\n  \"type\": \"module\",\n  \"packageManager\": \"pnpm@11.22.0\",\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\",\n    \"dsh\": \">=0.2.0-rc.1 <0.3.0-0\"\n  },\n  \"main\": \"lib/index.mjs\",\n  \"types\": \"lib/index.d.mts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.mts\",\n      \"default\": \"./lib/index.mjs\"\n    },\n    \"./client\": {\n      \"default\": \"./lib/client.js\"\n    },\n    \"./session-title\": {\n      \"types\": \"./lib/session-title-plugin.d.mts\",\n      \"default\": \"./lib/session-title-plugin.mjs\"\n    },\n    \"./settings-skin\": {\n      \"types\": \"./lib/settings-skin-plugin.d.mts\",\n      \"default\": \"./lib/settings-skin-plugin.mjs\"\n    },\n    \"./composer\": {\n      \"types\": \"./lib/composer-plugin.d.mts\",\n      \"default\": \"./lib/composer-plugin.mjs\"\n    },\n    \"./sidebar\": {\n      \"types\": \"./lib/sidebar-plugin.d.mts\",\n      \"default\": \"./lib/sidebar-plugin.mjs\"\n    },\n    \"./theme\": {\n      \"types\": \"./lib/theme-plugin.d.mts\",\n      \"default\": \"./lib/theme-plugin.mjs\"\n    },\n    \"./package.json\": \"./package.json\",\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./session-title/locale/*.json\": \"./locale/session-title/*.json\",\n    \"./settings-skin/locale/*.json\": \"./locale/settings-skin/*.json\",\n    \"./composer/locale/*.json\": \"./locale/composer/*.json\",\n    \"./sidebar/locale/*.json\": \"./locale/sidebar/*.json\",\n    \"./theme/locale/*.json\": \"./locale/theme/*.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"assets\",\n    \"locale\",\n    \"cordis.patch.yml\",\n    \"CHANGELOG.md\",\n    \"CHANGELOG.zh-CN.md\",\n    \"LICENSE\",\n    \"README.md\",\n    \"README.zh-CN.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-input-trigger\",\n        \"@deepseek-ai/dsh-session\",\n        \"@deepseek-ai/dsh-client-ui-layout\",\n        \"@deepseek-ai/dsh-client-ui-workspace\",\n        \"@deepseek-ai/dsh-client-ui-theme\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"tsc --noEmit && tsdown\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"test\": \"pnpm run typecheck && vitest run && tsdown && node tests/run-assertions.mjs && pnpm run test:layout\",\n    \"test:host\": \"node scripts/verify-native-settings.mjs\",\n    \"test:layout\": \"node scripts/verify-new-conversation.mjs && node scripts/verify-hero-width.mjs\",\n    \"test:compat\": \"node scripts/run-compat-host.mjs\",\n    \"test:fallback-host\": \"node scripts/verify-plugin-fallback-host.mjs\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \">=4.0.2 <5.0.0\",\n    \"@deepseek-ai/dsh-client-connection\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-locale\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-input-trigger\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-layout\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-settings-general\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-sidebar\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-theme\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-workspace\": \">=0.2.0-rc.1 <0.3.0-0\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.5\",\n    \"@deepseek-ai/dsh-api-session-controller\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-api-workspace-controller\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-attachment\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-connection\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-test-runtime\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-chat\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-input-trigger\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-layout\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-session\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-settings-general\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-sidebar\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-theme\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-workspace\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-scope\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-session\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-subagent\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-util-workspace-path\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-workspace\": \"0.2.1-rc.3\",\n    \"@types/jsdom\": \"^30.0.0\",\n    \"@types/node\": \"^26.0.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"^18.3.7\",\n    \"diff\": \"^9.0.0\",\n    \"jsdom\": \"^29.1.1\",\n    \"playwright\": \"1.63.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"shiki\": \"^4.3.1\",\n    \"simple-icons\": \"16.31.0\",\n    \"tsdown\": \"^0.22.2\",\n    \"tsx\": \"^4.22.4\",\n    \"typescript\": \"^6.0.3\",\n    \"vitest\": \"^4.1.8\",\n    \"workflow-yaml\": \"npm:yaml@2.9.0\"\n  },\n  \"dependencies\": {\n    \"lucide-react\": \"^1.39.0\"\n  },\n  \"icon\": \"assets/icon.svg\"\n}\n"
    },
    {
      "path": "cordis.patch.yml",
      "content": "# 保留官方侧栏与设置壳，仅覆盖客户端渲染，停用后自动回退。\n# 标题提供方的回退单独管理。\n- insert:\n    - id: codex-ui-session-title\n      name: '@michengai/dsh-codex-ui/session-title'\n    - id: codex-ui-settings-skin\n      name: '@michengai/dsh-codex-ui/settings-skin'\n    - id: codex-ui-composer\n      name: '@michengai/dsh-codex-ui/composer'\n    - id: codex-ui-sidebar\n      name: '@michengai/dsh-codex-ui/sidebar'\n    - id: codex-ui-theme\n      name: '@michengai/dsh-codex-ui/theme'\n    - id: codex-ui\n      name: '@michengai/dsh-codex-ui'\n"
    },
    {
      "path": "src/client/index.ts",
      "content": "import type { Context as ClientContext } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-client-locale/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-renderer/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-settings/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-conversation/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-input-trigger/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-theme/client'\nimport type {} from '@deepseek-ai/dsh-session'\nimport { AboutSection } from './AboutSection.tsx'\nimport { en, NS, zh } from './locales.ts'\nimport { observeSettingsSkin } from './settings-skin/index.ts'\nimport { observeSettingsNavIcon } from './settings-nav-icon.ts'\nimport { observeComposerEnhancements } from './composer/index.tsx'\nimport { observeSidebarNav, checkSidebarEnabled } from './sidebar/index.ts'\nimport { observeWorkspaceSections } from './sidebar/sections/index.ts'\nimport { observeTheme } from './theme/index.ts'\n\nexport const inject = ['slots', 'locale', 'sessions', 'conversation', 'inputTriggers', 'layout', 'uiWorkspace']\n\n/** 浏览器客户端插件入口；保留官方原生侧边栏与工作区树，提供输入框增强、设置美化与生态关于页。 */\nexport function apply(ctx: ClientContext): void {\n  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'michengai-codex-ui: dictionaries')\n  const t = ctx.locale.bind(NS)\n\n  ctx.effect(() => observeTheme(ctx), 'michengai-codex-ui: theme & appearance')\n  ctx.effect(() => observeSidebarNav(ctx), 'michengai-codex-ui: sidebar navigation')\n  // 工作区分区随侧栏子插件一起启停：探活失败（子插件被停用或 Host 路由缺失）时不注入任何标题。\n  ctx.effect(() => {\n    let stop: (() => void) | undefined\n    let cancelled = false\n    void checkSidebarEnabled().then(enabled => {\n      if (cancelled || !enabled) return\n      const translate = (key: string, fallback?: string): string => {\n        try {\n          const value = (t as unknown as (name: string) => string)(key)\n          return typeof value === 'string' && value !== '' && value !== key ? value : (fallback ?? key)\n        } catch {\n          return fallback ?? key\n        }\n      }\n      stop = observeWorkspaceSections(ctx, translate)\n    })\n    return () => {\n      cancelled = true\n      stop?.()\n    }\n  }, 'michengai-codex-ui: workspace sections')\n  ctx.effect(() => observeComposerEnhancements(ctx), 'michengai-codex-ui: composer enhancements')\n  ctx.effect(() => observeSettingsSkin(), 'michengai-codex-ui: official settings skin')\n  ctx.effect(() => observeSettingsNavIcon(() => t('about.nav')), 'michengai-codex-ui: settings nav icon')\n\n  ctx.slots.inject('settings.section', () => ctx.slots.register({\n    name: 'settings.section',\n    id: 'codex-ui',\n    order: Number.MAX_SAFE_INTEGER,\n    label: () => t('about.nav'),\n    locale: NS,\n  }, AboutSection))\n}\n"
    },
    {
      "path": "src/client/composer/InputHistoryDock.tsx",
      "content": "import { useEffect, useRef } from 'react'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-client-ui-renderer/client'\nimport type { SessionId } from '@deepseek-ai/dsh-session/types'\nimport type { PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'\nimport type {} from '@deepseek-ai/dsh-client-ui-input-trigger/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-conversation/client'\nimport { InputHistory } from './input-history.ts'\nimport { hasDraftAttachments } from './draft-attachments.ts'\nimport { bindHistoryKeys, findComposer } from './input-history-keyboard.ts'\nimport { NS } from '../locales.ts'\n\nexport function InputHistoryHint({ t }: PropsLocale<typeof NS>) {\n  // 跟随宿主占位元素的显隐和位置，避免占用工具栏或覆盖实际输入。\n  return <style>{`\n    [data-composer-card] [data-input-scroll]{container:dcu-composer-input / inline-size}\n    [data-composer-card] [data-composer-placeholder]{display:flex;align-items:baseline;justify-content:space-between;gap:12px}\n    [data-composer-card] [data-composer-placeholder]::after{\n      content:${JSON.stringify(t('input.historyHint'))};\n      color:var(--dsw-alias-label-caption);font-size:12px;line-height:18px;\n      white-space:nowrap;flex:0 0 auto;margin-right:8px;\n    }\n    @container dcu-composer-input (max-width:560px){\n      [data-composer-card] [data-composer-placeholder]::after{display:none}\n    }\n    @media(max-width:640px){\n      [data-composer-card] [data-composer-placeholder]::after{display:none}\n    }\n  `}</style>\n}\n\ntype HistoryDockProps = {\n  ctx: Context\n  sessionId: SessionId\n  history: InputHistory\n  seen: WeakMap<object, number>\n}\n\n/** 隐形输入扩展：使用宿主状态和编辑动作，不替换编辑器或创建旁问界面。 */\nexport function InputHistoryDock({ ctx, sessionId, history, seen }: HistoryDockProps) {\n  const anchor = useRef<HTMLSpanElement>(null)\n  useEffect(() => {\n    const binding = ctx.sessions.binding(sessionId)\n    if (binding === undefined) return\n    const scope = ctx.sessions.list.getSnapshot().byId[sessionId]?.cwd ?? sessionId\n    const input = ctx.conversation.input.for(binding.ctx)\n    const menu = ctx.inputTriggers.sessionOf(binding.ctx).menu\n    // 挂载只建立版本基线，历史窗口和未挂载期间的输入不回灌；多实例共用版本去重。\n    seen.set(binding, binding.eventSource.getSnapshot().revision)\n    const collect = () => {\n      const snapshot = binding.eventSource.getSnapshot()\n      // 完整窗口替换可重设版本基线，兼容宿主重建窗口后计数归零；不回灌窗口内容。\n      if (snapshot.change.kind !== 'replace' && snapshot.revision <= (seen.get(binding) ?? -1)) return\n      seen.set(binding, snapshot.revision)\n      if (snapshot.change.kind !== 'append') return\n      for (const entry of snapshot.change.entries) {\n        if (entry.event.type !== 'user/message' || entry.event.data.source?.kind !== 'user') continue\n        const text = entry.event.data.content.filter(block => block.type === 'text').map(block => block.text).join('')\n        history.add(scope, text)\n      }\n    }\n    const offEvents = binding.eventSource.subscribe(collect)\n    let previous = input.state.getSnapshot()\n    const offInput = input.state.subscribe(() => {\n      const next = input.state.getSnapshot()\n      // 宿主成功提交命令后才清空草稿并回到 plain；失败保留 claimed 和原文。\n      if (previous.phase === 'submitting' && next.phase === 'plain' && next.draft === ''\n        && !hasDraftAttachments(previous) && previous.occurrences.length === 0) {\n        history.add(scope, previous.draft)\n      }\n      previous = next\n    })\n    let editor: HTMLElement | undefined\n    let offKeys = () => {}\n    const connect = () => {\n      const next = anchor.current === null ? undefined : findComposer(anchor.current)\n      if (next === editor) return\n      offKeys()\n      editor = next\n      if (editor === undefined) return\n      offKeys = bindHistoryKeys(editor, {\n        draft: () => input.state.getSnapshot().draft,\n        entries: () => history.list(scope),\n        setDraft: text => input.setDraft(text),\n        blocked: () => {\n          const state = input.state.getSnapshot()\n          return state.phase === 'adjudicating' || state.phase === 'submitting'\n            || hasDraftAttachments(state) || state.occurrences.length > 0 || menu.getSnapshot().open\n        },\n      })\n    }\n    connect()\n    const parent = anchor.current?.parentElement?.parentElement\n    const observer = new MutationObserver(connect)\n    if (parent !== null && parent !== undefined) observer.observe(parent, { childList: true, subtree: true })\n    return () => { observer.disconnect(); offKeys(); offInput(); offEvents() }\n  }, [ctx, sessionId, history, seen])\n  return <span ref={anchor} hidden />\n}\n\nexport function registerInputHistory(ctx: Context): () => void {\n  let storage: Storage | undefined\n  try { storage = window.localStorage } catch { console.warn('[michengai-codex-ui] 浏览器存储不可用，使用内存输入历史。') }\n  const history = new InputHistory(storage)\n  const seen = new WeakMap<object, number>()\n  function Dock(props: PropsRuntime<'conversation.input.dock'>) {\n    return <InputHistoryDock ctx={ctx} sessionId={props.session.sessionId} history={history} seen={seen} />\n  }\n  const unregisterDock = ctx.slots.inject('conversation.input.dock', () => ctx.slots.register({\n    name: 'conversation.input.dock', id: 'codex-ui-input-history', order: -100,\n  }, Dock))\n  const unregisterHint = ctx.slots.inject('conversation.input.dock', () => ctx.slots.register({\n    name: 'conversation.input.dock', id: 'codex-ui-input-history-hint', order: -100, locale: NS,\n  }, InputHistoryHint))\n  return () => {\n    unregisterDock()\n    unregisterHint()\n  }\n}\n"
    },
    {
      "path": "src/client/composer/input-history.ts",
      "content": "export const HISTORY_KEY = 'michengai.codex-ui.input-history.v1'\nconst LEGACY_HISTORY_KEY = 'michengai.btw.history.v1'\nconst MAX_STORAGE_LENGTH = 1_000_000\ntype StorageFace = Pick<Storage, 'getItem' | 'setItem'>\n\n/** 只保存已发送文本；浏览器存储失败时仍保留本次内存历史。 */\nexport class InputHistory {\n  private readonly scopes = new Map<string, string[]>()\n  constructor(private readonly storage?: StorageFace, private readonly limit = 200, private readonly warn: (message: string) => void = console.warn) {\n    try {\n      const current = storage?.getItem(HISTORY_KEY)\n      const raw = current ?? storage?.getItem(LEGACY_HISTORY_KEY)\n      if (!raw) return\n      if (raw.length > MAX_STORAGE_LENGTH) throw new Error('历史数据过大')\n      const data: unknown = JSON.parse(raw)\n      if (typeof data !== 'object' || data === null || Array.isArray(data)) throw new Error('历史格式无效')\n      for (const [key, value] of Object.entries(data).slice(-20)) {\n        if (Array.isArray(value)) this.scopes.set(key, value.filter((item): item is string => typeof item === 'string' && item.length <= 8_000).slice(-limit))\n      }\n      // 迁移后只写新键，保留旧数据供回退；已有新键时不重复导入。\n      if (current === null || current === undefined) storage?.setItem(HISTORY_KEY, JSON.stringify(Object.fromEntries(this.scopes)))\n    } catch { warn('输入历史读取失败，本次使用内存历史。') }\n  }\n  list(scope: string): readonly string[] { return this.scopes.get(scope) ?? [] }\n  add(scope: string, text: string): void {\n    if (!text.trim() || text.length > 8_000) return\n    const previous = this.scopes.get(scope) ?? []\n    if (previous.at(-1) === text) return\n    this.scopes.delete(scope)\n    this.scopes.set(scope, [...previous, text].slice(-this.limit))\n    while (this.scopes.size > 20) this.scopes.delete(this.scopes.keys().next().value!)\n    let serialized = JSON.stringify(Object.fromEntries(this.scopes))\n    while (serialized.length > MAX_STORAGE_LENGTH && this.scopes.size) {\n      const oldest = this.scopes.keys().next().value!\n      const entries = this.scopes.get(oldest)!\n      entries.shift()\n      if (!entries.length) this.scopes.delete(oldest)\n      serialized = JSON.stringify(Object.fromEntries(this.scopes))\n    }\n    try { this.storage?.setItem(HISTORY_KEY, serialized) }\n    catch { this.warn('输入历史无法保存到浏览器，本次仍可使用。') }\n  }\n}\n\n/** 从空输入进入，编辑历史即退出，避免覆盖用户的新草稿。 */\nexport class HistoryCursor {\n  private index: number | undefined\n  private original = ''\n  private displayed = ''\n  private entries: readonly string[] = []\n\n  reset(): void { this.index = undefined; this.entries = [] }\n  move(direction: -1 | 1, draft: string, entries: readonly string[]): string | undefined {\n    if (this.index !== undefined && draft !== this.displayed) this.reset()\n    if (this.index === undefined) {\n      if (direction !== -1 || draft !== '' || entries.length === 0) return undefined\n      this.original = draft\n      this.entries = [...entries]\n      this.index = this.entries.length\n    }\n    this.index = Math.max(0, Math.min(this.entries.length, this.index + direction))\n    if (this.index === this.entries.length) {\n      const restored = this.original\n      this.reset()\n      return restored\n    }\n    this.displayed = this.entries[this.index] ?? ''\n    return this.displayed\n  }\n}\n"
    },
    {
      "path": "src/client/composer/new-conversation-draft.ts",
      "content": "import { hasDraftAttachments } from './draft-attachments.ts'\n\nexport type PrefillResult = 'ready' | 'workspace' | 'draft' | 'busy'\nexport type DraftPresenceSource = { getSnapshot: () => boolean; subscribe: (listener: () => void) => () => void }\ntype DraftState = { getSnapshot: () => { draft: string }; subscribe: (listener: () => void) => () => void }\n\n/** 跟随当前会话的原草稿状态，覆盖输入、粘贴、历史召回和任务预填。 */\nexport function createDraftPresenceSource(selection: Pick<DraftState, 'subscribe'>, resolve: () => DraftState | undefined): DraftPresenceSource {\n  return {\n    getSnapshot: () => (resolve()?.getSnapshot().draft.length ?? 0) > 0,\n    subscribe: listener => {\n      let current: DraftState | undefined\n      let offInput = () => {}\n      const bind = () => {\n        const next = resolve()\n        if (next !== current) {\n          offInput()\n          current = next\n          offInput = next?.subscribe(listener) ?? (() => {})\n        }\n        listener()\n      }\n      const offSelection = selection.subscribe(bind)\n      bind()\n      return () => { offSelection(); offInput() }\n    },\n  }\n}\ntype DraftInput = {\n  state: { getSnapshot: () => { phase: string; draft: string; imageIds?: readonly unknown[]; attachmentIds?: readonly unknown[]; occurrences: readonly unknown[] } }\n  setDraft: (text: string) => void\n}\n\n/** 任务建议只能填入空闲且空白的草稿，不覆盖附件、提及或正在提交的内容。 */\nexport function prefillNewConversation(input: DraftInput | undefined, text: string): PrefillResult {\n  if (input === undefined) return 'workspace'\n  const state = input.state.getSnapshot()\n  if (state.phase !== 'plain') return 'busy'\n  if (state.draft.trim() !== '' || hasDraftAttachments(state) || state.occurrences.length > 0) return 'draft'\n  input.setDraft(text)\n  return 'ready'\n}\n"
    }
  ],
